// Student info form
// ============================================================
function InfoForm({ T, lang, info, setInfo, errors, onBack, onContinue }) {
  const update = (k, v) => setInfo({ ...info, [k]: v });

  return (
    <div className="poder-screen">
      <div className="poder-stack">
        <h2 className="poder-h2">{T("infoTitle")}</h2>
        <p className="poder-body">{T("infoSub")}</p>

        <Field label={T("fullName")} hint={T("fullNameH")} error={errors.name}>
          <input
            type="text"
            value={info.name}
            onChange={(e) => update("name", e.target.value)}
            autoComplete="name"
            className="poder-input"
          />
        </Field>

        <Field label={T("phone")} hint={T("phoneH")} error={errors.phone}>
          <input
            type="tel"
            value={info.phone}
            onChange={(e) => update("phone", e.target.value)}
            autoComplete="tel"
            inputMode="tel"
            className="poder-input"
          />
        </Field>

        <Field label={T("email")} hint={T("emailH")} error={errors.email}>
          <input
            type="email"
            value={info.email}
            onChange={(e) => update("email", e.target.value)}
            autoComplete="email"
            inputMode="email"
            className="poder-input"
          />
        </Field>

        <Field label={T("classTime")} error={errors.classTime}>
          <div className="poder-choice-grid">
            <ChoiceTile
              selected={info.classTime === "morning"}
              onClick={() => update("classTime", "morning")}
              icon="☀️"
              label={T("morning")}
              color={BRAND.yellow}
            />
            <ChoiceTile
              selected={info.classTime === "evening"}
              onClick={() => update("classTime", "evening")}
              icon="🌙"
              label={T("evening")}
              color={BRAND.blue}
            />
          </div>
        </Field>

        <div className="poder-btn-row">
          <button className="poder-btn-ghost" onClick={onBack}>← {T("back")}</button>
          <button className="poder-btn-primary" onClick={onContinue}>{T("continue")} →</button>
        </div>
      </div>
    </div>
  );
}

function Field({ label, hint, error, children }) {
  return (
    <label className="poder-field">
      <span className="poder-field-label">{label}</span>
      {children}
      {hint && !error && <span className="poder-field-hint">{hint}</span>}
      {error && <span className="poder-field-err">{error}</span>}
    </label>
  );
}

function ChoiceTile({ selected, onClick, icon, label, color }) {
  return (
    <button
      type="button"
      className={"poder-choice-tile" + (selected ? " selected" : "")}
      onClick={onClick}
      style={selected ? { borderColor: color, background: color + "20" } : {}}
      aria-pressed={selected}
    >
      <span className="poder-choice-tile-icon">{icon}</span>
      <span className="poder-choice-tile-label">{label}</span>
    </button>
  );
}

// ============================================================
// Test block (sticky context + question list)
// ============================================================
function TestBlock({ T, lang, block, blockIdx, answers, onAnswer, onPrev, onNext, submitting }) {
  const hasContext = block.contextType !== "none";
  const promptText = T(block.promptKey);

  return (
    <div className="poder-test-shell">
      {hasContext && (
        <div className="poder-context-sticky">
          <div className="poder-context-prompt">{promptText}</div>
          <ContextRenderer block={block} />
        </div>
      )}

      <div className="poder-questions">
        {!hasContext && (
          <div className="poder-context-prompt poder-context-prompt--inline">{promptText}</div>
        )}
        {block.qs.map((qNum) => (
          <QuestionCard
            key={qNum}
            qNum={qNum}
            q={QUESTIONS[qNum]}
            selected={answers[qNum]}
            onAnswer={(c) => onAnswer(qNum, c)}
            T={T}
          />
        ))}
      </div>

      <div className="poder-btn-row poder-btn-row--sticky">
        <button className="poder-btn-ghost" onClick={onPrev} disabled={submitting}>← {T("previous")}</button>
        <span className="poder-block-counter">{blockIdx + 1} / {BLOCKS.length}</span>
        <button
          className={"poder-btn-primary" + (blockIdx === BLOCKS.length - 1 ? " poder-btn-primary--final" : "")}
          onClick={onNext}
          disabled={submitting}
        >
          {blockIdx === BLOCKS.length - 1
            ? (submitting ? T("submitting") : T("submit")) + " ✓"
            : T("next") + " →"}
        </button>
      </div>
    </div>
  );
}

function ContextRenderer({ block }) {
  if (block.contextType === "image") {
    return <img src={block.imgSrc} alt={block.imgAlt} className="poder-context-img" />;
  }
  if (block.contextType === "notice") {
    return (
      <div className="poder-notice">
        <strong>Notice from Carmina's Restaurant</strong>
        <p>Come and visit Carmina's Restaurant. It opens today. It is across from the bank. It is next to the library. The restaurant is open on Wednesday, Thursday, Friday, and Saturday. Welcome to Carmina's!</p>
      </div>
    );
  }
  if (block.contextType === "schedule") {
    return (
      <div className="poder-scroll-x">
        <table className="poder-table">
          <caption>Day-Care Center Work Schedule</caption>
          <thead>
            <tr><th>Name</th><th>Days</th><th>Hours</th></tr>
          </thead>
          <tbody>
            <tr><td rowSpan="2">Sally</td><td>Tu Th</td><td>12:00 – 8:00 p.m.</td></tr>
            <tr><td>Sat Sun</td><td>10:00 a.m. – 3:00 p.m.</td></tr>
            <tr><td>Dan</td><td>Tu Th F</td><td>9:00 a.m. – 5:00 p.m.</td></tr>
            <tr><td rowSpan="2">Megan</td><td>M W F</td><td>12:00 – 8:00 p.m.</td></tr>
            <tr><td>Sat</td><td>9:00 a.m. – 5:00 p.m.</td></tr>
            <tr><td rowSpan="2">Juan</td><td>M W</td><td>9:00 a.m. – 5:00 p.m.</td></tr>
            <tr><td>Sat Sun</td><td>12:00 – 5:00 p.m.</td></tr>
          </tbody>
        </table>
      </div>
    );
  }
  if (block.contextType === "catalog") {
    return (
      <div className="poder-catalog">
        <h4>COURSE CATALOG</h4>
        <div className="poder-catalog-grid">
          <div>
            <strong>General Equivalency Diploma (GED)</strong>
            <p>Do you want to get your GED? Then you need to practice your reading, writing, and math skills. Classes are in English or Spanish. No fee.</p>
            <p><em>Instructor: Mr. Chen (English) / Ms. Lopez (Spanish)<br/>Days/Times: Mon, Wed 6:00 p.m. – 8:00 p.m.</em></p>
          </div>
          <div>
            <strong>Introduction to Computers</strong>
            <p>This class is for adults who want to learn about computers and the Internet. You will learn about keyboarding, e-mail, and computer jobs. Fee: $75</p>
            <p><em>Instructor: Mrs. Gates<br/>Days/Times: Mon, Wed 7:00 p.m. – 9:00 p.m.</em></p>
          </div>
          <div>
            <strong>TV and DVD Repair</strong>
            <p>This class will teach you how to repair TVs and DVD players. You will also learn about opening your own repair shop. Fee: $85</p>
            <p><em>Instructor: Mr. Stern<br/>Days/Times: Mon, Tues 6:00 p.m. – 8:00 p.m.</em></p>
          </div>
          <div>
            <strong>Citizenship</strong>
            <p>Do you want to be an American citizen? First, you need to learn about American history and civics. This class will prepare you for the U.S. citizenship test. Requirements: Legal resident. No fee.</p>
            <p><em>Instructor: Ms. Cuevas<br/>Days/Times: Thurs 7:00 p.m. – 9:00 p.m.</em></p>
          </div>
        </div>
      </div>
    );
  }
  if (block.contextType === "story") {
    return (
      <div className="poder-story">
        {STORIES[block.storyKey].split("\n\n").map((para, i) => (
          <p key={i}>{para}</p>
        ))}
      </div>
    );
  }
  return null;
}

function QuestionCard({ qNum, q, selected, onAnswer, T }) {
  const letters = ["a","b","c","d"];
  return (
    <div className="poder-q-card">
      <div className="poder-q-head">
        <span className="poder-q-num">{qNum}</span>
        <span className="poder-q-stem">{q.stem}</span>
      </div>
      <div className="poder-choices">
        {letters.filter((l) => q.choices[l] !== undefined).map((letter) => (
          <button
            key={letter}
            type="button"
            className={"poder-choice" + (selected === letter ? " selected" : "")}
            onClick={() => onAnswer(letter)}
            aria-pressed={selected === letter}
          >
            <span className="poder-choice-letter">{letter}</span>
            <span className="poder-choice-text">{q.choices[letter]}</span>
          </button>
        ))}
      </div>
    </div>
  );
}

